            var w0 = plotKey === 'mdh' ? line.t0 : line.x0, w1 = plotKey === 'mdh' ? line.t1 : line.x1;
            if (xa == null || xb == null) { xa = Math.min(w0, w1); xb = Math.max(w0, w1); }
