        try { ad = typeof G.PRiSM_getAnalysisData === 'function' ? G.PRiSM_getAnalysisData() : null; } catch (e) { ad = null; }
        var spec = (ad && ad.ok && ad.mpSpec) ? ad.mpSpec : { T_F: T_F, SG_g: sg, pmax: 1.2 * (isPos(w.piStored) ? w.piStored : 5000) };
